class Solution {
public:
    vector<bool> isArraySpecial(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> group(n, 0);
        for (int i = 1; i < n; i++) {
            if ((nums[i] & 1) == (nums[i - 1] & 1)) {
                group[i] = group[i - 1] + 1;
            } else {
                group[i] = group[i - 1];
            }
        }
        vector<bool> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            ans.push_back(group[q[0]] == group[q[1]]);
        }
        return ans;
    }
};
